from pathlib import Path
r=Path('yolk-survivors')
for file in ['scenes/units/unit.gd','scenes/weapons/melee/catalogue_melee_behaviour.gd','scenes/projectiles/baguette_harpoon.gd','scenes/projectiles/pressure_pot.gd']:
 p=r/file;s=p.read_text(encoding='utf-8-sig')
 s=s.replace('source_stats.get_effect_multiplier() * source_stats.effect_duration_multiplier() * source_stats.get_crowd_control_multiplier()', 'source_stats.get_crowd_control_multiplier()')
 s=s.replace('weapon.get_parent().stats.get_effect_multiplier() * weapon.get_parent().stats.effect_duration_multiplier()', 'weapon.get_parent().stats.get_crowd_control_multiplier()')
 s=s.replace('hitbox.source.stats.get_effect_multiplier() * hitbox.source.stats.effect_duration_multiplier()', 'hitbox.source.stats.get_crowd_control_multiplier()')
 s=s.replace('hitbox.launch_duration = tuning.launch_duration','hitbox.launch_duration = tuning.launch_duration * weapon.get_parent().stats.get_crowd_control_multiplier()')
 p.write_text(s,encoding='utf-8')
p=r/'scenes/projectiles/catalogue_projectile.gd';s=p.read_text(encoding='utf-8-sig').replace('hitbox.launch_duration = effects.airbourne_duration','hitbox.launch_duration = effects.airbourne_duration * (hitbox.source.stats.get_crowd_control_multiplier() if hitbox.source is Unit else 1.0)');p.write_text(s,encoding='utf-8')
p=r/'effects/status_controller.gd';s=p.read_text(encoding='utf-8-sig').replace('effect.duration * strength * (source_stats.effect_duration_multiplier()', 'effect.duration * (source_stats.effect_duration_multiplier()');p.write_text(s,encoding='utf-8')
p=r/'resources/items/passives/catalogue/item_003.tres';s=p.read_text(encoding='utf-8-sig').replace('description = "+Daño de efectos"','description = "+3 de Efectos. Acumulable por copia. No modifica el control de masas."').replace('effect_key = ""','effect_key = "oregano"').replace('ready_for_shop = false','ready_for_shop = true').replace('pending_reason = "Definir magnitudes numéricas de las bonificaciones y/o penalizaciones."','pending_reason = ""\nadd_value = 3.0\nadd_stats_id = "effects"');p.write_text(s,encoding='utf-8')
p=r/'resources/items/passives/catalogue.gd';p.write_text(p.read_text(encoding='utf-8-sig').replace('ACTIVE_IDS := [1, 2, 13','ACTIVE_IDS := [1, 2, 3, 13'),encoding='utf-8')
p=r/'tests/verify_catalogue_passives.gd';p.write_text(p.read_text(encoding='utf-8-sig').replace('catalogue.size() == 28','catalogue.size() == 29'),encoding='utf-8')
p=r/'tests/verify_catalogue_shop.gd';p.write_text(p.read_text(encoding='utf-8-sig').replace('+ player.passive_items.count("cumin"))','+ player.passive_items.count("cumin") + player.passive_items.count("oregano"))'),encoding='utf-8')
p=r/'docs/item_catalogue_status.md';p.write_text(p.read_text(encoding='utf-8-sig').replace('28 activos; 72 pendientes','29 activos; 71 pendientes').replace('Pimentón, Comino,','Pimentón, Comino, Orégano,').replace('| 003 | Orégano | Definir magnitudes numéricas de las bonificaciones y/o penalizaciones. |','| 003 | Orégano | Implementado: +3 de Efectos por copia; sin escalado de control. |'),encoding='utf-8')
p=r/'docs/combat_stats_and_statuses.md';s=p.read_text(encoding='utf-8-sig');s=s.replace('+1% spicy and status damage, +1% slow and immobilization duration per point.','+1% chili and status damage per point. Slow, Rooted and Airbourne scale exclusively with Crowd control.').replace('Source Effects scales electric damage and slow duration.','Source Effects scales electric damage only. Electricity does not slow.').replace('Existing grater hold duration and pan slow duration also use Effects.','Grater hold, harpoon pin and pan slow durations use Crowd control; Airbourne speed and duration also use Crowd control.');p.write_text(s,encoding='utf-8')

